package edu.hfut.incidents.controller;import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.cloud.client.loadbalancer.LoadBalancerClient;import org.springframework.cloud.netflix.ribbon.SpringClientFactory;import com.netflix.loadbalancer.*;import com.netflix.hystrix.*;import edu.hfut.incidents.service.IncidentService;import edu.hfut.incidents.dao.IncidentMapper;import static edu.hfut.incidents.service.impl.IncidentServiceImpl.map;
@RestController @RequestMapping("/internal")public class InternalController{
 private final IncidentService s;private final IncidentMapper d;private final SpringClientFactory f;private final LoadBalancerClient lb;@Value("${server.port}")int port;@Value("${P4C_FAULT_INJECTION:false}")boolean faults;
 public InternalController(IncidentService s,IncidentMapper d,SpringClientFactory f,LoadBalancerClient lb){this.s=s;this.d=d;this.f=f;this.lb=lb;}
 @PostMapping("/blacklist-check")public Object check(@RequestBody Map<String,Object>b){return s.check(b,false);}
 @PostMapping("/access-blacklist")public Object access(@RequestBody Map<String,Object>b){return s.check(b,true);}
 @PostMapping("/access-result")public Object event(@RequestBody Map<String,Object>b){Map<String,Object>ack=s.accept(b);if(faults&&d.fault("ack")>0)try{Thread.sleep(4000);}catch(InterruptedException e){Thread.currentThread().interrupt();}return ack;}
 @GetMapping("/projection")public Object projection(){return s.projection();}
 @GetMapping("/components")public Object components(){ILoadBalancer b=f.getLoadBalancer("user-service");List<Object>commands=new ArrayList<>();for(HystrixCommandMetrics m:HystrixCommandMetrics.getInstances()){HystrixCircuitBreaker cb=HystrixCircuitBreaker.Factory.getInstance(m.getCommandKey());commands.add(map("command",m.getCommandKey().name(),"open",cb!=null&&cb.isOpen(),"requests",m.getHealthCounts().getTotalRequests(),"errors",m.getHealthCounts().getErrorCount(),"failures",m.getRollingCount(HystrixEventType.FAILURE),"shortCircuits",m.getRollingCount(HystrixEventType.SHORT_CIRCUITED),"fallback",m.getRollingCount(HystrixEventType.FALLBACK_SUCCESS)));}return map("service","exception-service","port",port,"client",lb.getClass().getName(),"loadBalancer",b.getClass().getName(),"servers",b.getAllServers().toString(),"rule",((BaseLoadBalancer)b).getRule().getClass().getName(),"handledBy",((edu.hfut.incidents.service.impl.IncidentServiceImpl)s).instanceCounts(),"hystrix",commands);}
}
